def _decode_classification_table() -> tuple[_ClassificationRow, ...]:
    payload = zlib.decompress(base64.b85decode(_TABLE_B85.encode("ascii")))
    raw_rows = json.loads(payload.decode("utf-8"))
    return tuple(cast(_ClassificationRow, tuple(row)) for row in raw_rows)


_CLASSIFICATION_TABLE: Final[tuple[_ClassificationRow, ...]] = (
    _decode_classification_table()
)
CLASSIFICATION_TABLE_SIZE: Final[int] = len(_ENTRY_CORE)

__all__ = [
    "CLASSIFICATION_TABLE_SIZE",
    "_CLASSIFICATION_TABLE",
    "_CROSSREF_ROW_INDEX",
    "_ENTRY_CORE",
    "_OPENALEX_ROW_INDEX",
    "_PUBMED_ROW_INDEX",
    "_S2_ROW_INDEX",
]
